import json, sys
R = []
def rfs(s): R.append({"kind": "requestfs", "input": s.encode().hex() if isinstance(s, str) else s.hex()})
def rf(b): R.append({"kind": "readFile", "input": b.hex() if isinstance(b, bytes) else b.encode().hex()})
# request filesystem: valid objects and duplicates at every nesting level
rfs('{"kind":"layer","files":{"/a.ts":"1","/b.ts":"2"}}')
rfs('{"kind":"layer","kind":"full"}')
rfs('{"kind":"layer","files":{"/a.ts":"1","/a.ts":"2"}}')
rfs('{"kind":"layer","files":{"/a.ts":"1","/\\u0061.ts":"2"}}')
rfs('{"kind":"layer","files":{"/a.ts":"1","/A.ts":"2"}}')
rfs('{"kind":"layer","files":{},"files":{}}')
rfs('{"kind":"layer","directories":{"/d":{"files":["x"],"files":["y"]}}}')
rfs('{"kind":"layer","directories":{"/d":{"files":["x"]},"/d":{"files":["y"]}}}')
rfs('{"kind":"layer","symlinks":{"/l":{"target":"/t","target":"/u"}}}')
rfs('{"kind":"layer","symlinks":{"/l":{"target":"/t","host":true,"host":false}}}')
rfs('{"kind":"layer","removedPaths":["/a","/a"]}')
rfs('{"kind":"layer","unknownField":{"x":1,"x":2}}')
rfs('{"kind":"layer","unknownField":{"x":1,"y":[{"z":1},{"z":2}]}}')
rfs('{"kind":"layer","files":{"/a.ts":"x\\ud800y"}}')
rfs('{"kind":"layer","files":{"/\\ud800.ts":"x"}}')
rfs('{"kind":"layer","Kind":"full"}')
rfs('{"kind":"layer","files":null,"directories":null,"symlinks":null,"removedPaths":null}')
rfs('null')
rfs(b'{"kind":"layer","files":{"/a.ts":"x\xed\xa0\x80y"}}')
rfs(b'{"kind":"layer","files":{"/a.ts":"x\xffy"}}')
# readFile callback responses (sync: JSON.stringify output; async: vscode-jsonrpc JSON.stringify)
rf('{"kind":"value","value":"plain \\ud83d\\ude00"}')
rf('{"kind":"value","value":"x\\ud800y"}')
rf('{"kind":"value","value":"x\\udc00y"}')
rf('{"kind":"value","value":"x\\ud800\\ud800y"}')
rf('{"kind":"value","value":"x\\udc00\\ud800y"}')
rf('{"kind":"value","value":"\\ud800"}')
rf(b'{"kind":"value","value":"x\xed\xa0\x80y"}')
rf(b'{"kind":"value","value":"x\xffy"}')
rf('{"kind":"value","value":"x\\u0000y"}')
rf('{"kind":"value","kind":"missing"}')
rf('{"kind":"value","value":"a","value":"b"}')
def jr(s): R.append({"kind": "jsonrpc", "input": s.encode().hex() if isinstance(s, str) else s.hex()})
jr('{"jsonrpc":"2.0","id":"api1","result":{"kind":"value","value":"x\\ud800y"}}')
jr('{"jsonrpc":"2.0","id":1,"method":"m","params":{"a":1,"a":2}}')
jr('{"jsonrpc":"2.0","id":1,"method":"m","params":{"a":[{"b":1},{"b":1,"b":2}]}}')
jr('{"jsonrpc":"2.0","id":1,"method":"m","params":{"a~/b":{"c":1,"c":2}}}')
jr('{"jsonrpc":"2.0","id":1,"method":"m","params":"\\udc00"}')
jr(b'{"jsonrpc":"2.0","id":1,"method":"m","params":"\xc3"}')
jr('{"jsonrpc":"2.0","id":1,"method":"m","params":"ok \\ud83d\\ude00 \\u00e9"}')
json.dump(R, sys.stdout)
